function validate([a, b]) {
  if (!Number.isInteger(a) || a < 1 || a > 2147483647) return 'a is between 1 and 2^31 - 1.';
  if (!Array.isArray(b) || b.length < 1 || b.length > 2000) return 'b needs 1 to 2000 digits.';
  if (b.some(d => !Number.isInteger(d) || d < 0 || d > 9)) return 'Each entry of b is a digit from 0 to 9.';
  if (b[0] === 0) return 'b must not start with 0.';
  return null;
}

