function superPow(a, b) {
  const MOD = 1337;
  const base = a % MOD;
  let result = 1;

  for (const digit of b) {
    let next = 1;
    for (let k = 0; k < 10; k++) {
      next = (next * result) % MOD;
    }
    for (let k = 0; k < digit; k++) {
      next = (next * base) % MOD;
    }
    result = next;
  }
  return result;
}

