function superPow(a, b) {
  const mod = 1337n;
  let exponent = 0n;
  for (const d of b) exponent = exponent * 10n + BigInt(d);
  let x = BigInt(a) % mod, answer = 1n;
  while (exponent > 0n) {
    if (exponent & 1n) answer = answer * x % mod;
    x = x * x % mod;
    exponent >>= 1n;
  }
  return Number(answer);
}

