function generate(rand, size) {
  const pick = () => {
    const r = rand();
    if (r < 0.15) return 1 + Math.floor(rand() * 5);
    if (r < 0.3) return 7 * (1 + Math.floor(rand() * 300));
    if (r < 0.45) return 191 * (1 + Math.floor(rand() * 50));
    if (r < 0.55) return 1337 * (1 + Math.floor(rand() * 20)) + Math.floor(rand() * 3) - 1;
    if (r < 0.75) return 1 + Math.floor(rand() * 3000);
    return 1 + Math.floor(rand() * 2147483647);
  };
  const a = pick();
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 6);
  const b = Array.from({ length: n }, () => Math.floor(rand() * 10));
  b[0] = 1 + Math.floor(rand() * 9);
  return [a, b];
}
